export type IconKind = "png" | "jpeg";

export interface DirectoryEntry {
  readonly key: string;
  readonly endpoint: string;
  readonly kind: IconKind;
  readonly bytes: Uint8Array;
}

export class IconDirectory {
  private readonly entries = new Map<string, DirectoryEntry>();

  constructor(private readonly maximumBytes: number) {
    if (!Number.isFinite(maximumBytes) || !Number.isInteger(maximumBytes) || maximumBytes <= 0) {
      throw new RangeError("maximumBytes must be a positive integer");
    }
  }

  put(key: string, endpoint: string, bytes: Uint8Array): boolean {
    const normalizedKey = key.trim();
    const normalizedEndpoint = endpoint.trim();
    const kind = this.detect(bytes);
    if (
      normalizedKey.length === 0 ||
      normalizedEndpoint.length === 0 ||
      bytes.length === 0 ||
      bytes.length > this.maximumBytes ||
      kind === undefined
    ) {
      return false;
    }
    this.entries.set(normalizedKey, {
      key: normalizedKey,
      endpoint: normalizedEndpoint,
      kind,
      bytes,
    });
    return true;
  }

  get(key: string): DirectoryEntry | undefined {
    const entry = this.entries.get(key.trim());
    return entry === undefined ? undefined : { ...entry, bytes: new Uint8Array(entry.bytes) };
  }

  keys(): string[] {
    return [...this.entries.keys()].sort();
  }

  private detect(bytes: Uint8Array): IconKind | undefined {
    const png = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];
    if (bytes.length >= png.length && png.every((value, index) => bytes[index] === value)) {
      return "png";
    }
    if (
      bytes.length >= 5 &&
      bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff &&
      bytes[bytes.length - 2] === 0xff && bytes[bytes.length - 1] === 0xd9
    ) {
      return "jpeg";
    }
    return undefined;
  }
}

