import { IconDirectory } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function bytesEqual(actual: Uint8Array, expected: readonly number[], message: string): void {
  assert(actual.length === expected.length, `${message}: length differs`);
  for (let i = 0; i < expected.length; i += 1) equal(actual[i], expected[i], `${message} at ${i}`);
}
function rangeError(action: () => void, message: string): void {
  try { action(); } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: expected RangeError`);
}

for (const invalid of [0, -1, 1.5, NaN, Infinity]) {
  rangeError(() => new IconDirectory(invalid), `invalid maximum ${String(invalid)}`);
}

const directory = new IconDirectory(10);
const png = new Uint8Array([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
equal(directory.put('  logo  ', '  /logo.png  ', png), true, 'valid PNG is stored');
png[0] = 0;
const logo = directory.get(' logo ')!;
equal(logo.key, 'logo', 'key is normalized');
equal(logo.endpoint, '/logo.png', 'endpoint is normalized');
equal(logo.kind, 'png', 'PNG kind detected');
bytesEqual(logo.bytes, [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a], 'input bytes are copied');

const logoAgain = directory.get('logo')!;
assert(logoAgain !== logo, 'get returns a fresh entry');
assert(logoAgain.bytes !== logo.bytes, 'get returns fresh bytes');
logo.bytes[1] = 0;
equal(directory.get('logo')!.bytes[1], 0x50, 'returned bytes cannot mutate storage');
(logo as { endpoint: string }).endpoint = 'changed';
equal(directory.get('logo')!.endpoint, '/logo.png', 'returned entry cannot mutate storage');

const jpeg = new Uint8Array([0xff, 0xd8, 0xff, 0x01, 0xff, 0xd9]);
equal(directory.put('a', '/a.jpg', jpeg), true, 'valid JPEG is stored');
equal(directory.get('a')!.kind, 'jpeg', 'JPEG kind detected');
equal(directory.put('logo', '/new.jpg', jpeg), true, 'normalized key is replaced');
equal(directory.get(' logo ')!.endpoint, '/new.jpg', 'replacement is visible');
equal(directory.get('logo')!.kind, 'jpeg', 'replacement updates kind');

equal(directory.put('z', '/z', new Uint8Array([0xff, 0xd8, 0xff, 0xff, 0xd9])), true, 'minimum-length JPEG is valid');
equal(directory.keys().join(','), 'a,logo,z', 'keys use ascending code-unit order');
const keys = directory.keys();
keys.length = 0;
equal(directory.keys().join(','), 'a,logo,z', 'keys result cannot mutate directory');

equal(directory.get(''), undefined, 'blank lookup fails');
equal(directory.get('   '), undefined, 'whitespace lookup fails');
equal(directory.get('missing'), undefined, 'unknown lookup fails');

const prior = directory.keys().join(',');
equal(directory.put(' ', '/x', jpeg), false, 'blank key rejected');
equal(directory.put('x', ' ', jpeg), false, 'blank endpoint rejected');
equal(directory.put('x', '/x', new Uint8Array()), false, 'empty bytes rejected');
equal(directory.put('x', '/x', new Uint8Array(11)), false, 'oversized bytes rejected');
equal(directory.put('x', '/x', new Uint8Array([0xff, 0xd8, 0xff, 0, 0])), false, 'JPEG without ending marker rejected');
equal(directory.put('x', '/x', new Uint8Array([0xff, 0xd8, 0xff, 0xd9])), false, 'too-short JPEG rejected');
equal(directory.put('x', '/x', new Uint8Array([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0])), false, 'incorrect PNG prefix rejected');
equal(directory.keys().join(','), prior, 'failed puts do not mutate keys');

